// R42: every knowledge card has a landing page (public/c/<id>.html) and a preview picture (public/og/<id>.jpg),
// generated by scripts/og-cards.mjs; this keeps them in step with the cards (re-run the script when a card changes).
import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { lvOf } from '../../src/l4/share/card';

const web = join(__dirname, '..', '..'), pub = join(web, 'public');
const load = (f: string) => JSON.parse(readFileSync(join(web, 'src/l4/c', f), 'utf8')) as Record<string, { n: string }>;
const zh = { ...load('k-zh.json'), ...load('k1-zh.json'), ...load('k3-zh.json') }, en = { ...load('k-en.json'), ...load('k1-en.json'), ...load('k3-en.json') };
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const HOME = ['#L4', '#L1', '#L2', '#L3', '#L4', '#L5'];

describe('R42 card landing pages + OG pictures', () => {
  it('one page and one picture per card, nothing extra', () => {
    const ids = Object.keys(zh).sort();
    expect(ids.length).toBe(53);
    expect(readdirSync(join(pub, 'c')).sort()).toEqual(ids.map((i) => `${i}.html`));
    expect(readdirSync(join(pub, 'og')).sort()).toEqual(ids.map((i) => `${i}.jpg`));
  });
  it('each page: og meta for the card, redirect into the app at the card, a visible fallback link', () => {
    for (const id of Object.keys(zh)) {
      const h = readFileSync(join(pub, 'c', `${id}.html`), 'utf8'), hash = `${HOME[lvOf(id).n]}~${id}`;
      expect(h).toContain(`<title>${esc(zh[id]!.n)} · 大白话拆解 AI</title>`);
      expect(h).toContain(`<p class="en">${esc(en[id]!.n)}</p>`);
      expect(h).toContain(`<meta property="og:image" content="https://superjackman.github.io/SI/og/${id}.jpg">`);
      expect(h).toContain(`<meta property="og:url" content="https://superjackman.github.io/SI/c/${id}.html">`);
      expect(h).toMatch(/og:description" content="[^"]{8,}"/);
      expect(h).toContain(`'${hash}'`);
      expect(h).toContain(`href="../?lang=zh${hash}"`);
      expect(h).toContain(`href="../?lang=en${hash}"`);
      const j = readFileSync(join(pub, 'og', `${id}.jpg`));
      expect(j[0]).toBe(0xff); expect(j[1]).toBe(0xd8); expect(j.length).toBeLessThan(200_000);
    }
  });
  it('og.png is 1200×630 and small enough for chat previews', () => {
    const p = readFileSync(join(pub, 'og.png'));
    expect(p.subarray(1, 4).toString()).toBe('PNG');
    expect([p.readUInt32BE(16), p.readUInt32BE(20)]).toEqual([1200, 630]);
    expect(p.length).toBeLessThan(300_000);
  });
  it('index.html + manifest: dark (#0b1230) theme, no white flash', () => {
    const html = readFileSync(join(web, 'index.html'), 'utf8'), m = JSON.parse(readFileSync(join(pub, 'manifest.webmanifest'), 'utf8'));
    expect(html).toContain('<meta name="theme-color" content="#0b1230">');
    expect(html).toContain('html,body{margin:0;background:#0b1230');
    expect(html).not.toContain('#f6f7fb');
    expect([m.theme_color, m.background_color]).toEqual(['#0b1230', '#0b1230']);
  });
});
